const indexes = { en: 0, zh: 1, tw: 2 };
export function careerText(key, language = 'en', params = {}) {
  if (!Object.hasOwn(CAREER_COPY, key)) throw new Error(`Missing career translation: ${key}`);
  return CAREER_COPY[key][indexes[language] ?? 0].replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(params, name) ? String(params[name]) : match);
}
export function languageName(language, uiLanguage = 'en') {
  return ({ en: ['English', 'Simplified Chinese', 'Traditional Chinese'], zh: ['英语', '简体中文', '繁体中文'], tw: ['英語', '簡體中文', '繁體中文'] }[uiLanguage] || ['English', 'Simplified Chinese', 'Traditional Chinese'])[indexes[language] ?? 0];
}
export function localizeKnownText(text, language = 'en') {
  for (const [key, versions] of Object.entries(CAREER_COPY)) if (versions.includes(text)) return careerText(key, language);
  return text;
}

