export function localizeCareerError(message, language = 'en') {
  const index = indexes[language] ?? 0;
  const suffix = ' Add any new facts to the fact list and regenerate.';
  if (message.endsWith(suffix)) return localizeCareerError(message.slice(0, -suffix.length), language) + [' Add any new facts to the fact list and regenerate.', ' 请将新事实添加至事实列表并重新生成。', ' 請將新事實加入事實清單並重新產生。'][index];
  const exact = ERRORS.find(versions => versions.includes(message));
  if (exact) return exact[index];
  const check = /^Check (.+) \(maximum (\d+) characters\)\.$/.exec(message);
  if (check) {
    const fields = { company: 'company', role: 'role', 'job description': 'jd', 'display name': 'displayName', city: 'city', contact: 'contact', skills: 'skills', headline: 'headline', introduction: 'about', 'CV text': 'sourceNotes', 'fact text': 'factsTitle', 'translated headline': 'headline', 'translated introduction': 'about', 'draft item': 'draftWording', 'section heading': 'draftWording', 'review question': 'questions' };
    const field = fields[check[1]] ? careerText(fields[check[1]], language) : ['this field', '此字段', '此欄位'][index];
    return [`Check ${field} (maximum ${check[2]} characters).`, `请检查${field}（最多 ${check[2]} 个字符）。`, `請檢查${field}（最多 ${check[2]} 個字元）。`][index];
  }
  if (message.startsWith('AI translation is not configured.')) return [message, '尚未配置 AI 翻译。请为每条事实填写并确认目标语言的文字，或选择已有的语言。', '尚未設定 AI 翻譯。請為每項事實填寫並確認目標語言的文字，或選擇已有的語言。'][index];
  const provider = /The AI service could not complete this request \((\d+)\)/.exec(message);
  if (provider) return [message, `AI 服务暂时无法完成请求（${provider[1]}）。事实未变更，请稍后重试。`, `AI 服務暫時無法完成請求（${provider[1]}）。事實未變更，請稍後重試。`][index];
  return index === 0 ? message : careerText('errorGeneric', language);
}
